import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor conv2d_forward(torch::Tensor x,
                              torch::Tensor w,
                              c10::optional<torch::Tensor> b,
                              int stride_h, int stride_w,
                              int pad_h, int pad_w,
                              int dil_h, int dil_w);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T>
__global__ void conv2d_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ Bp,
    T* __restrict__ Y,
    int N, int Cin, int H, int Win,
    int Cout, int Kh, int Kw,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dil_h, int dil_w,
    int Hout, int Wout)
{
  constexpr int Threads    = 128;
  constexpr int PVec       = 4;
  constexpr int CoPerBlock = 4;
  constexpr int KChunk     = 64;

  const int tid = threadIdx.x;

  const int n       = blockIdx.z;
  const int co_tile = blockIdx.y;
  const int co_base = co_tile * CoPerBlock;

  const int P_total = Hout * Wout;
  const int PTile   = Threads * PVec;
  const int p_block = blockIdx.x * PTile;

  const int K     = Cin * Kh * Kw;
  const int KhKw  = Kh * Kw;

  const int64_t sXn = (int64_t)Cin * H * Win;
  const int64_t sXc = (int64_t)H * Win;
  const int64_t sXh = (int64_t)Win;

  const int64_t sYn = (int64_t)Cout * Hout * Wout;
  const int64_t sYc = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;

  // Global tensors via CuTe
  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(Cin, H, Win),
      make_stride(sXc, sXh, Int<1>{})
  );

  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(Cout, Hout, Wout),
      make_stride(sYc, sYh, Int<1>{})
  );

  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(Cout, K),
      make_stride(K, Int<1>{})
  );

  __shared__ T sW_raw[CoPerBlock * KChunk];
  auto sW = make_tensor(
      make_smem_ptr(sW_raw),
      make_shape(Int<CoPerBlock>{}, Int<KChunk>{}),
      make_stride(Int<KChunk>{}, Int<1>{})
  );

  int p_idx[PVec];
  int oh_arr[PVec];
  int ow_arr[PVec];

  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    int p = p_block + tid + i * Threads;
    p_idx[i] = p;
    if (p < P_total) {
      oh_arr[i] = p / Wout;
      ow_arr[i] = p - oh_arr[i] * Wout;
    } else {
      oh_arr[i] = 0;
      ow_arr[i] = 0;
    }
  }

  float acc[CoPerBlock][PVec];
  #pragma unroll
  for (int cc = 0; cc < CoPerBlock; ++cc) {
    int co = co_base + cc;
    float bval = 0.0f;
    if (Bp != nullptr && co < Cout) {
      bval = (float)Bp[co];
    }
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      acc[cc][i] = bval;
    }
  }

  for (int k0 = 0; k0 < K; k0 += KChunk) {
    // Load weight chunk into shared memory
    for (int kk = tid; kk < KChunk; kk += Threads) {
      int k_global = k0 + kk;
      #pragma unroll
      for (int cc = 0; cc < CoPerBlock; ++cc) {
        int co = co_base + cc;
        T wval = T(0);
        if (co < Cout && k_global < K) {
          wval = mW(co, k_global);
        }
        sW(cc, kk) = wval;
      }
    }
    __syncthreads();

    #pragma unroll
    for (int kk = 0; kk < KChunk; ++kk) {
      int k_global = k0 + kk;
      if (k_global >= K) break;

      int cin = k_global / KhKw;
      int rem = k_global - cin * KhKw;
      int kh  = rem / Kw;
      int kw  = rem - kh * Kw;

      #pragma unroll
      for (int i = 0; i < PVec; ++i) {
        int p = p_idx[i];
        if (p >= P_total) continue;

        int ih = oh_arr[i] * stride_h - pad_h + kh * dil_h;
        if ((unsigned)ih >= (unsigned)H) continue;

        int iw = ow_arr[i] * stride_w - pad_w + kw * dil_w;
        if ((unsigned)iw >= (unsigned)Win) continue;

        float xval = (float)mX(cin, ih, iw);

        #pragma unroll
        for (int cc = 0; cc < CoPerBlock; ++cc) {
          int co = co_base + cc;
          if (co >= Cout) continue;
          float wval = (float)sW(cc, kk);
          acc[cc][i] += xval * wval;
        }
      }
    }
    __syncthreads();
  }

  #pragma unroll
  for (int cc = 0; cc < CoPerBlock; ++cc) {
    int co = co_base + cc;
    if (co >= Cout) continue;

    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      int p = p_idx[i];
      if (p >= P_total) continue;
      mY(co, oh_arr[i], ow_arr[i]) = static_cast<T>(acc[cc][i]);
    }
  }
}

torch::Tensor conv2d_forward(torch::Tensor x,
                              torch::Tensor w,
                              c10::optional<torch::Tensor> b,
                              int stride_h, int stride_w,
                              int pad_h, int pad_w,
                              int dil_h, int dil_w) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");

  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");

  TORCH_CHECK(x.dim() == 4, "x must be [N, Cin, H, W]");
  TORCH_CHECK(w.dim() == 4, "w must be [Cout, Cin, Kh, Kw]");

  int64_t N    = x.size(0);
  int64_t Cin  = x.size(1);
  int64_t H    = x.size(2);
  int64_t Win  = x.size(3);

  int64_t Cout = w.size(0);
  TORCH_CHECK(w.size(1) == Cin, "w.size(1) must equal Cin (groups=1 only)");
  int64_t Kh = w.size(2);
  int64_t Kw = w.size(3);

  TORCH_CHECK(stride_h > 0 && stride_w > 0, "stride must be > 0");
  TORCH_CHECK(pad_h >= 0 && pad_w >= 0, "padding must be >= 0");
  TORCH_CHECK(dil_h > 0 && dil_w > 0, "dilation must be > 0");

  int64_t Hout = (H + 2 * pad_h - dil_h * (Kh - 1) - 1) / stride_h + 1;
  int64_t Wout = (Win + 2 * pad_w - dil_w * (Kw - 1) - 1) / stride_w + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0, "Invalid output size computed");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [Cout]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, Cout, Hout, Wout}, x.options());

  constexpr int Threads    = 128;
  constexpr int PVec       = 4;
  constexpr int CoPerBlock = 4;
  const int64_t P_total = Hout * Wout;
  const int64_t PTile   = Threads * PVec;

  dim3 block(Threads);
  dim3 grid(
      (unsigned)((P_total + PTile - 1) / PTile),
      (unsigned)((Cout + CoPerBlock - 1) / CoPerBlock),
      (unsigned)N
  );

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  conv2d_kernel<float><<<grid, block, 0, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)Cin, (int)H, (int)Win,
      (int)Cout, (int)Kh, (int)Kw,
      stride_h, stride_w,
      pad_h, pad_w,
      dil_h, dil_w,
      (int)Hout, (int)Wout
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
"""

conv2d_ext = load_inline(
    name="cute_conv2d_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["conv2d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Standard 2D convolution with square input and asymmetric kernel,
    with dilation and padding, implemented with a custom CUDA kernel using CuTe.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple,
                 stride: int = 1, padding: tuple = (0, 0), dilation: tuple = (1, 1),
                 bias: bool = False):
        super().__init__()
        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = kernel_size
        self.stride = int(stride)
        self.padding = padding
        self.dilation = dilation

        kh, kw = kernel_size
        self.weight = nn.Parameter(torch.empty(out_channels, in_channels, kh, kw))
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()
        self._ext = conv2d_ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            kh, kw = self.kernel_size
            fan_in = self.in_channels * kh * kw
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        pad_h, pad_w = self.padding
        dil_h, dil_w = self.dilation
        return self._ext.conv2d_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias if self.bias is not None else None,
            self.stride, self.stride,
            pad_h, pad_w,
            dil_h, dil_w,
        )

